T=$(mktemp -d); S=~/.claude/skills/taskbar-icons/scripts; H=$T/home; mkdir -p $H/.config/omarchy/bar/modules $T/scratch; cp ~/.config/omarchy/bar/modules/taskbar-icons.js $H/.config/omarchy/bar/modules/; printf 'repo=%s\n' "$T/repo" > $H/.config/omarchy/desktop.conf
echo "== friend"; cd $T/scratch; HOME=$H $S/icon-new htop "htop: bracketed CPU meters" && sed -i 's|    circle(12, 12, 8.5),|    path("M7 4.5H4.5v15H7M17 4.5h2.5v15H17"),\n    path("M8 9h6M8 12h8M8 15h4"),|' htop.icon.py && cp htop.icon.py htop-b.icon.py && HOME=$H $S/icon-set htop htop.icon.py --program htop; HOME=$H $S/icon-set --list | tail -1; python3 -c "import json;d=json.load(open('$H/.config/omarchy/taskbar-icons.json'));print(list(d['icons']), d['programs'])"; find $H/.config/omarchy/taskbar-icons-src -type f | sed "s|$H/||"; HOME=$H $S/icon-lint | tail -1
echo "== refuse bad"; printf '"""bad: out of bounds."""\nfrom iconkit import *\nicon(rect(0, 0, 24, 24))\n' > bad.icon.py; HOME=$H $S/icon-set bad bad.icon.py; echo "exit $?"
echo "== maintainer"; mkdir -p $T/repo/icon-src; cp -r ~/Projects/personal/omarchy-desktop/icon-src/icons $T/repo/icon-src/; printf 'repo=%s\nmaintainer=on\n' "$T/repo" > $H/.config/omarchy/desktop.conf; cp $H/.config/omarchy/bar/modules/taskbar-icons.js $T/before.js; sed 's/htop/demo/g' htop.icon.py > demo.icon.py; HOME=$H $S/icon-set demo demo.icon.py; grep -c '"demo"' $H/.config/omarchy/bar/modules/taskbar-icons.js; ls $T/repo/icon-src/icons | wc -l; HOME=$H $S/icon-build --check; rm -rf $T
